114	    public static String formatToken(String s, int chunkSize) {
115	        if (chunkSize ==0 || s == null)
116	            return s;
117	
118	        StringBuilder ret = new StringBuilder("");
119	        int index = s.length();
120	        while (index > 0) {
121	            ret.insert(0, s.substring(Math.max(index - chunkSize, 0), index));
122	            ret.insert(0, " ");
123	            index = index - chunkSize;
124	        }
125	        return ret.toString().trim();
126	    }
