/* Parse an int, returning the given fallback value if the input is not a valid int
   (e.g. empty, not a number or out of the range of an int) */
public static int parseIntWithFallback(String s, int fallback) {
    if (s == null)
        return fallback;

    try {
        return Integer.parseInt(s.trim());
    } catch (NumberFormatException e) {
        return fallback;
    }
}

/* Parse a long, returning the given fallback value if the input is not a valid long
   (e.g. empty, not a number or out of the range of a long) */
public static long parseLongWithFallback(String s, long fallback) {
    if (s == null)
        return fallback;

    try {
        return Long.parseLong(s.trim());
    } catch (NumberFormatException e) {
        return fallback;
